WITH fixes(slug,position,expected,explanation) AS (VALUES
('contabilidade-cebraspe-tce-ms-2025-auditor-ciencias-contabeis',7,'As classes 7 e 8 do PCASP são contas patrimoniais.','Errado. No PCASP, as classes 7 e 8 são de controles devedores e credores, respectivamente; as classes 1 e 2 são de ativo e passivo/patrimônio líquido.'),
('contabilidade-cebraspe-tce-ms-2025-auditor-ciencias-contabeis',9,'Despesa empenhada e liquidada, mas não paga, é RPP.','Correto. Restos a pagar processados são despesas empenhadas e liquidadas que não foram pagas até o encerramento do exercício.'),
('contabilidade-cebraspe-tce-rs-2025-ciencias-contabeis',3,'Perda por redução ao valor recuperável é VPA.','Errado. Uma perda por redução ao valor recuperável diminui a situação patrimonial e é reconhecida como variação patrimonial diminutiva (VPD), não aumentativa.'),
('contabilidade-cebraspe-tce-rs-2025-ciencias-contabeis',8,'Restos a pagar processados são despesas empenhadas e liquidadas, mas não pagas.','Correto. A despesa já passou pelas fases de empenho e liquidação, faltando o pagamento; essa é a característica dos restos a pagar processados.'),
('contabilidade-cebraspe-tce-rs-2025-ciencias-contabeis',10,'O limite prudencial corresponde a 90% do limite máximo de pessoal.','Errado. O limite prudencial da despesa total com pessoal corresponde a 95% do limite máximo aplicável, nos termos do art. 22, parágrafo único, da LRF; 90% é outro patamar de alerta.'),
('contabilidade-cebraspe-tce-rs-2025-ciencias-contabeis',12,'Índice de liquidez corrente de 0,83 indica insuficiência de ativo circulante para cobrir passivo circulante.','Correto. Liquidez corrente = ativo circulante / passivo circulante. Índice 0,83 significa R$ 0,83 de ativo circulante para cada R$ 1,00 de passivo circulante.'),
('contabilidade-gabriel-rabelo-exemplos-cfc-2020-1-simulado',5,'O custo por equivalente é R$ 50 quando o custo total é R$ 5.000 e há 1.000 unidades equivalentes.','Errado. O custo por unidade equivalente é custo total dividido pelas unidades equivalentes: R$ 5.000 / 1.000 = R$ 5, e não R$ 50.'),
('contabilidade-gabriel-rabelo-exemplos-cfc-2020-1-simulado',10,'Com estoque inicial 30 mil, compras líquidas 80 mil e estoque final 40 mil, o CMV é 70 mil.','Correto. Custo das mercadorias vendidas = estoque inicial + compras líquidas − estoque final = 30.000 + 80.000 − 40.000 = R$ 70.000.')
), matches AS (SELECT sm.id,f.position,f.explanation FROM study_materials sm JOIN fixes f ON f.slug=sm.slug WHERE sm.quiz->(f.position-1)->>'q'=f.expected)
UPDATE study_materials sm SET quiz=(SELECT jsonb_agg(CASE WHEN e.ordinality=m.position THEN jsonb_set(e.value,'{why}',to_jsonb(m.explanation)) ELSE e.value END ORDER BY e.ordinality) FROM jsonb_array_elements(sm.quiz) WITH ORDINALITY e(value,ordinality)),updated_at=now()
FROM matches m WHERE sm.id=m.id;